import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { Helmet } from 'react-helmet';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import CourseCard from './components/CourseCard';
import { useToast } from '../../contexts/ToastContext';
import { refreshContent, enrollStudentAsync, toggleLikeCourseAsync } from '../../store/contentSlice';
import { startCourse } from '../../store/activitySlice';
import { cn } from '../../utils/cn';
import { normalizeId } from '../../utils/idUtils';
import PaymentModal from './components/PaymentModal';
import CampIntakeModal from './components/CampIntakeModal';

const CourseCatalog = () => {
    const { addToast } = useToast();
    const navigate = useNavigate();
    const location = useLocation();
    const dispatch = useDispatch();
    const { isAuthenticated, user } = useSelector((state) => state.auth);
    const [searchQuery, setSearchQuery] = useState('');
    const [activeCategory, setActiveCategory] = useState('All');
    const [loadingCourseId, setLoadingCourseId] = useState(null);
    const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
    const [selectedCourse, setSelectedCourse] = useState(null);
    const [isGuestIntakeOpen, setIsGuestIntakeOpen] = useState(false);

    const academyCourses = useSelector((state) => state.content.academy) || [];
    const academyTracks = useSelector((state) => state.content.academyTracks) || [];
    const courseProgress = useSelector(state => state.activity.courseProgress);
    const likedCourses = JSON.parse(localStorage.getItem('luc_liked_courses') || '[]');

    // Silent Refresher - Keep counts and content fresh in background
    useEffect(() => {
        const interval = setInterval(() => {
            dispatch(refreshContent());
        }, 30000);
        return () => clearInterval(interval);
    }, [dispatch]);

    const categories = ['All', 'Scholarships', 'AI & Tech', 'Career Growth', 'Digital Marketing', 'Summer Camp 2026'];

    const trackCourseIds = new Set();
    academyTracks.forEach(track =>
        (track.courses || []).forEach(cId => trackCourseIds.add(normalizeId(cId)))
    );

    const filteredCourses = academyCourses.filter(course => {
        if (!course) return false;
        if (trackCourseIds.has(normalizeId(course.id))) return false;
        const matchesSearch = course.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            course.description.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesCategory = activeCategory === 'All' || course.category === activeCategory;
        return matchesSearch && matchesCategory;
    }).map(course => {
        const stringId = normalizeId(course.id);
        const userLiked = likedCourses.includes(stringId);
        const enrollment = courseProgress?.[stringId];

        return {
            ...course,
            progress: enrollment?.percentage || 0,
            isEnrolled: !!enrollment,
            likeCount: course.likes || 0,
            isLiked: userLiked
        };
    });

    // Intercept auto-enrollment parameter
    useEffect(() => {
        if (!isAuthenticated || !academyCourses.length) return;
        
        const params = new URLSearchParams(location.search);
        const enrollId = params.get('enroll');
        
        if (enrollId) {
            const courseToEnroll = academyCourses.find(c => c.id === enrollId || c.id === Number(enrollId));
            if (courseToEnroll) {
                const newUrl = window.location.pathname;
                window.history.replaceState({}, '', newUrl);

                const belongsToTrack = academyTracks.some(t =>
                    (t.courses || []).some(cId => normalizeId(cId) === normalizeId(courseToEnroll.id))
                );
                if (belongsToTrack) {
                    // Find the track and redirect to academy page with scroll
                    const parentTrack = academyTracks.find(t =>
                        (t.courses || []).some(cId => normalizeId(cId) === normalizeId(courseToEnroll.id))
                    );
                    if (parentTrack) {
                        navigate(`/academy?track=${parentTrack.id}`);
                    } else {
                        addToast('This course is part of a learning track. Please enroll in the full track on the Academy page.', 'warning');
                    }
                    return;
                }

                setTimeout(() => handleEnroll(courseToEnroll), 500);
            }
        }
    }, [isAuthenticated, location.search, academyCourses]);

    const handleEnroll = (course) => {
        if (!isAuthenticated) {
            setSelectedCourse(course);
            setIsGuestIntakeOpen(true);
            return;
        }

        const belongsToTrack = academyTracks.some(t =>
            (t.courses || []).some(cId => normalizeId(cId) === normalizeId(course.id))
        );
        if (belongsToTrack) {
            const parentTrack = academyTracks.find(t =>
                (t.courses || []).some(cId => normalizeId(cId) === normalizeId(course.id))
            );
            if (parentTrack) {
                navigate(`/academy?track=${parentTrack.id}`);
            } else {
                addToast('This course is part of a learning track. Please enroll in the full track on the Academy page.', 'warning');
            }
            return;
        }

        const isInstructor = user?.id && (course.instructor_id === user.id || course.instructorId === user.id);
        if (isInstructor) {
            addToast('Redirecting to your Instructor Hub...', 'info');
            navigate('/instructor-dashboard');
            return;
        }

        const isEnrolled = courseProgress && courseProgress[course.id];

        if (Number(course.price) === 0 || course.price === 'Free') {
            setLoadingCourseId(course.id);
            if (!isEnrolled) {
                dispatch(enrollStudentAsync({ courseId: course.id, type: 'academy' }));
                dispatch(startCourse({ courseId: course.id }));
            }

            setTimeout(() => {
                setLoadingCourseId(null);
                navigate(`/academy/course/${course.id}`, { state: { course, type: 'academy' } });
            }, 1000);
        } else {
            if (isEnrolled) {
                addToast('You are already enrolled in this course.', 'info');
                navigate(`/academy/course/${course.id}`, { state: { course, type: 'academy' } });
                return;
            }
            setSelectedCourse(course);
            setIsPaymentModalOpen(true);
        }
    };

    const handleToggleLike = (courseId) => {
        if (!isAuthenticated) {
            addToast('Please Login to like courses', 'info');
            navigate('/login');
            return;
        }
        // Simplified for catalog use
        const isLiked = likedCourses.includes(courseId.toString());
        dispatch(toggleLikeCourseAsync({ courseId, increment: !isLiked }));
        addToast(isLiked ? "Removed from favorites" : "Added to favorites!", "success");
        
        const newLiked = isLiked 
            ? likedCourses.filter(id => id !== courseId.toString())
            : [...likedCourses, courseId.toString()];
        localStorage.setItem('luc_liked_courses', JSON.stringify(newLiked));
    };

    return (
        <div className="min-h-screen bg-background flex flex-col">
            <Helmet>
                <title>Course Catalog | LUC Academy</title>
            </Helmet>
            <Header />

            <main className="flex-1 pt-8 pb-20">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <button 
                        onClick={() => navigate('/academy')}
                        className="flex items-center gap-2 text-muted-foreground hover:text-primary transition-colors mb-8 group"
                    >
                        <Icon name="ArrowLeft" size={18} className="group-hover:-translate-x-1 transition-transform" />
                        <span className="text-sm font-bold uppercase tracking-widest">Back to Academy</span>
                    </button>

                    {/* Header Section */}
                    <div className="text-center max-w-3xl mx-auto mb-16">
                        <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-primary/10 border border-primary/20 text-primary mb-6">
                            <Icon name="BookOpen" size={16} />
                            <span className="text-sm font-black uppercase tracking-widest italic">Course Catalog</span>
                        </div>
                        <h1 className="text-4xl md:text-6xl font-black text-primary leading-tight mb-6 italic tracking-tighter">
                            Master the <span className="text-secondary">Skills</span> of Tomorrow.
                        </h1>
                        <p className="text-lg text-muted-foreground">
                            Explore our comprehensive library of industry-led courses designed 
                            to take you from beginner to global professional.
                        </p>
                    </div>

                    {/* Search and Filters (Vault Style) */}
                    <div className="bg-card border border-border rounded-[2.5rem] p-6 mb-12 shadow-xl shadow-primary/5">
                        <div className="flex flex-col lg:flex-row gap-6">
                            <div className="flex-1 relative">
                                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground">
                                    <Icon name="Search" size={20} />
                                </div>
                                <input
                                    type="text"
                                    placeholder="Search courses by title, instructor, or skill..."
                                    className="w-full pl-12 pr-4 py-4 bg-background border-border rounded-2xl focus:ring-2 focus:ring-secondary/50 outline-none transition-all font-medium"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                />
                            </div>
                            <div className="flex flex-wrap gap-2">
                                {categories.map(cat => (
                                    <button
                                        key={cat}
                                        onClick={() => setActiveCategory(cat)}
                                        className={cn(
                                            "px-6 py-4 rounded-2xl text-sm font-black italic transition-all border",
                                            activeCategory === cat
                                                ? "bg-primary text-primary-foreground border-primary shadow-lg scale-105"
                                                : "bg-background border-border text-muted-foreground hover:border-primary/50"
                                        )}
                                    >
                                        {cat}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Results Grid */}
                    {filteredCourses.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {filteredCourses.map(course => (
                                <CourseCard
                                    key={course.id}
                                    course={course}
                                    isLoading={loadingCourseId === course.id}
                                    isEnrolled={course.isEnrolled}
                                    onEnroll={() => handleEnroll(course)}
                                    isLiked={course.isLiked}
                                    likeCount={course.likeCount}
                                    onLike={() => handleToggleLike(course.id)}
                                />
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-20 bg-muted/10 rounded-[3rem] border border-dashed border-border">
                            <Icon name="Frown" size={48} className="mx-auto mb-4 text-muted-foreground opacity-50" />
                            <h3 className="text-2xl font-bold text-primary">No courses found</h3>
                            <p className="text-muted-foreground mt-2">Try adjusting your filters or search term.</p>
                        </div>
                    )}
                </div>
            </main>

            <Footer />

            <PaymentModal
                isOpen={isPaymentModalOpen}
                onClose={() => setIsPaymentModalOpen(false)}
                course={selectedCourse}
                onPaymentSuccess={() => navigate(`/academy/course/${selectedCourse.id}`)}
            />

            {/* Guest "Who is enrolling?" gate — shown when not signed in */}
            <CampIntakeModal
                isOpen={isGuestIntakeOpen}
                onClose={() => setIsGuestIntakeOpen(false)}
                course={selectedCourse}
                isGuest={true}
                onIntakeComplete={(intakeData) => {
                    setIsGuestIntakeOpen(false);
                    sessionStorage.setItem('pendingIntake', JSON.stringify({
                        ...intakeData,
                        courseId: selectedCourse?.id,
                        courseTitle: selectedCourse?.title,
                        isTrack: selectedCourse?.isTrack || false,
                        trackCourses: selectedCourse?.courses || []
                    }));
                    addToast('Please create an account to complete your enrollment.', 'info');
                    navigate('/signup');
                }}
            />
        </div>
    );
};

export default CourseCatalog;
